{
  "topic_id": "dna_replication",
  "audience": "high_school",
  "evidence_grounding_note": "Only two retrieved passages were available; both are review abstracts from the same publisher (Annual Review of Biochemistry). They are not independent sources. Several expected mechanistic details (5'-to-3' addition at a free 3'-OH end, antiparallel templates, primer removal/ligation steps) are not present in the retrieved text and are therefore recorded as evidence gaps, not facts.",
  "facts": [
    {
      "fact_id": "F1",
      "claim": "Eukaryotic DNA replication begins at many sites in the genome called replication origins.",
      "scope": "Eukaryotic cells; initiation of replication",
      "classification": "established",
      "evidence_ids": ["PMID_35320688"],
      "support": [
        {
          "evidence_id": "PMID_35320688",
          "quote": "DNA replication in eukaryotic cells initiates from large numbers of sites called replication origins."
        }
      ]
    },
    {
      "fact_id": "F2",
      "claim": "Initiation from origins must be tightly controlled so that the whole genome is duplicated precisely once per cell cycle.",
      "scope": "Eukaryotic cells; cell-cycle control of replication initiation",
      "classification": "established",
      "evidence_ids": ["PMID_35320688"],
      "support": [
        {
          "evidence_id": "PMID_35320688",
          "quote": "Initiation of replication from these origins must be tightly controlled to ensure the entire genome is precisely duplicated in each cell cycle."
        }
      ]
    },
    {
      "fact_id": "F3",
      "claim": "Control of eukaryotic replication initiation is achieved by regulating loading and activation of the replicative DNA helicase.",
      "scope": "Eukaryotic cells; budding-yeast proteins emphasized in the review; helicase regulation",
      "classification": "established",
      "evidence_ids": ["PMID_35320688"],
      "support": [
        {
          "evidence_id": "PMID_35320688",
          "quote": "This is accomplished through the regulation of the first two steps in replication: loading and activation of the replicative DNA helicase."
        }
      ]
    },
    {
      "fact_id": "F4",
      "claim": "The bulk of leading-strand DNA synthesis at an undisturbed eukaryotic replication fork is carried out by DNA polymerase epsilon (Pol ε), according to the model supported by the preponderance of evidence.",
      "scope": "Eukaryotic replication fork; undisturbed fork; model-level claim",
      "classification": "established",
      "evidence_ids": ["PMID_28301743"],
      "support": [
        {
          "evidence_id": "PMID_28301743",
          "quote": "The preponderance of evidence supports a model in which DNA polymerase ε (Pol ε) carries out the bulk of leading strand DNA synthesis at an undisturbed replication fork."
        }
      ]
    },
    {
      "fact_id": "F5",
      "claim": "DNA polymerase alpha (Pol α) carries out initiation of Okazaki fragment synthesis.",
      "scope": "Eukaryotic lagging strand; Okazaki fragment initiation (priming step implied by source but not stated molecularly)",
      "classification": "established",
      "evidence_ids": ["PMID_28301743"],
      "support": [
        {
          "evidence_id": "PMID_28301743",
          "quote": "DNA polymerases α and δ carry out the initiation of Okazaki fragment synthesis and its elongation and maturation, respectively."
        }
      ]
    },
    {
      "fact_id": "F6",
      "claim": "DNA polymerase delta (Pol δ) carries out elongation and maturation of Okazaki fragments.",
      "scope": "Eukaryotic lagging strand; Okazaki fragment elongation and maturation",
      "classification": "established",
      "evidence_ids": ["PMID_28301743"],
      "support": [
        {
          "evidence_id": "PMID_28301743",
          "quote": "DNA polymerases α and δ carry out the initiation of Okazaki fragment synthesis and its elongation and maturation, respectively."
        }
      ]
    },
    {
      "fact_id": "F7",
      "claim": "The eukaryotic replication fork includes enzymes that synthesize DNA and enzymes that repair discontinuities on the lagging strand.",
      "scope": "Eukaryotic replication fork; enzyme roles",
      "classification": "established",
      "evidence_ids": ["PMID_28301743"],
      "support": [
        {
          "evidence_id": "PMID_28301743",
          "quote": "with an emphasis on the enzymes that synthesize DNA and repair discontinuities on the lagging strand of the replication fork"
        }
      ]
    },
    {
      "fact_id": "F8",
      "claim": "Alternative proposals exist, including that alternative replication forks may operate during certain cellular processes, and biochemical reconstitution studies separately and jointly examine leading- and lagging-strand synthesis.",
      "scope": "Eukaryotic replication fork; scope of current models and methods",
      "classification": "disputed",
      "evidence_ids": ["PMID_28301743"],
      "support": [
        {
          "evidence_id": "PMID_28301743",
          "quote": "This review also discusses alternative proposals, including cellular processes during which alternative forks may be utilized, and new biochemical studies with purified proteins that are aimed at reconstituting leading and lagging strand DNA synthesis separately and as an integrated replication fork."
        }
      ]
    }
  ],
  "mechanism": {
    "events": [
      {
        "event": "Origin licensing/activation and helicase loading/activation",
        "description": "Replication initiates at many origins; the first two regulated steps are loading and activation of the replicative DNA helicase.",
        "fact_ids": ["F1", "F2", "F3"]
      },
      {
        "event": "Leading-strand synthesis",
        "description": "At an undisturbed fork, Pol ε is modeled as synthesizing the bulk of the leading strand.",
        "fact_ids": ["F4"]
      },
      {
        "event": "Okazaki fragment initiation",
        "description": "Pol α initiates synthesis of Okazaki fragments on the lagging strand.",
        "fact_ids": ["F5"]
      },
      {
        "event": "Okazaki fragment elongation and maturation",
        "description": "Pol δ elongates Okazaki fragments and participates in their maturation; fork enzymes also repair discontinuities on the lagging strand.",
        "fact_ids": ["F6", "F7"]
      }
    ],
    "roles": [
      {
        "role": "Replicative DNA helicase",
        "description": "Its loading and activation are the regulated steps that control initiation.",
        "fact_ids": ["F3"]
      },
      {
        "role": "DNA polymerase epsilon (Pol ε)",
        "description": "Bulk leading-strand synthesis at an undisturbed fork (model supported by preponderance of evidence).",
        "fact_ids": ["F4"]
      },
      {
        "role": "DNA polymerase alpha (Pol α)",
        "description": "Initiates Okazaki fragment synthesis.",
        "fact_ids": ["F5"]
      },
      {
        "role": "DNA polymerase delta (Pol δ)",
        "description": "Elongates and matures Okazaki fragments.",
        "fact_ids": ["F6"]
      }
    ],
    "constraints": [
      {
        "constraint": "Initiation must be tightly controlled so the genome is duplicated precisely once per cell cycle.",
        "fact_ids": ["F2"]
      },
      {
        "constraint": "The Pol ε leading-strand assignment is a model supported by the preponderance of evidence, not an absolute rule; alternative proposals and alternative fork contexts are discussed.",
        "fact_ids": ["F4", "F8"]
      },
      {
        "constraint": "Okazaki fragment synthesis requires initiation before elongation and maturation; these are distinct steps assigned to Pol α and Pol δ respectively.",
        "fact_ids": ["F5", "F6"]
      }
    ]
  },
  "assumptions": [
    "The retrieved passages are review abstracts; mechanism statements are summaries of evidence reviewed elsewhere, not primary measurements in the supplied text.",
    "Both evidence items come from the same publisher (Annual Review of Biochemistry), so cross-source independence is not established.",
    "Budding-yeast proteins are emphasized in PMID_35320688; generalization to all eukaryotes is an assumption of the review's framing, not directly verified in the passage.",
    "The review's statement about Pol ε is explicitly model-level ('preponderance of evidence supports a model'), so it should be taught as the current leading model, not as an exceptionless fact."
  ],
  "evidence_gaps": [
    "No retrieved passage states 5'-to-3' addition at a free 3'-OH end; this detail is not included as a fact.",
    "No retrieved passage states that the two template strands are antiparallel; not included as a fact.",
    "No retrieved passage specifies RNA primer synthesis, primer removal, gap filling, or ligation during Okazaki maturation; 'maturation' is named but its molecular steps are not supported here.",
    "No retrieved passage gives the directionality of leading vs lagging synthesis or the geometry of Okazaki fragment joining.",
    "No measurements or quantitative data were retrieved; all claims are qualitative mechanism statements."
  ],
  "status": "PROVISIONAL",
